// Turns compiler and engine messages into something a young coder can act on.

export type FriendlyError = {
  title: string;
  hint: string;
  line: number | null;
  raw: string;
};

const TOKEN_NAMES: Record<string, string> = {
  PASCAL_IDENTIFIER: 'a name that starts with a capital letter',
  IDENTIFIER: 'a lowercase name',
  NEWLINE: 'the end of the line',
  INDENT: 'a Tab at the start of the line',
  DEDENT: 'one less Tab',
  COLON: 'a colon (:)',
  '<EOF>': 'the end of the program',
};

function describe(text: string): string {
  return text.replace(/\b[A-Z_]{3,}\b|<EOF>/g, (token) => TOKEN_NAMES[token] ?? token.toLowerCase());
}

const show = (s: string) => (s === "'\\n'" || s === "'\\r\\n'" ? 'the end of the line' : s);

export function friendlyError(message: string, kind: 'compile' | 'runtime'): FriendlyError {
  const raw = message.trim();
  const first = raw.replace(/^Parsing failed:\n/, '').split('\n')[0];
  const lineMatch = first.match(/line (\d+)/i);
  const line = lineMatch ? Number(lineMatch[1]) : null;
  const detail = first.replace(/^line \d+:\d+\s*/, '');

  let title = kind === 'compile' ? 'Sandscript could not read your code' : 'Your world stopped';
  let hint = detail;

  let m: RegExpMatchArray | null;
  if ((m = detail.match(/^missing (.+?) at (.+)$/))) {
    title = `Something is missing on line ${line}`;
    hint = m[1] === "':'"
      ? 'Add a colon (:) at the end of this line. Lines that start a block, like "if" or "has function", end with a colon.'
      : `Sandscript expected ${describe(m[1])} before ${show(m[2])}.`;
  } else if (/expecting PASCAL_IDENTIFIER/.test(detail)) {
    title = `Check the name on line ${line}`;
    hint = 'Element names start with a capital letter, like Sand or Water.';
  } else if (/Spaces cannot be used for indentation/.test(detail)) {
    title = `Use Tab on line ${line}`;
    hint = 'Sandscript lines up code with the Tab key, not spaces. Delete the spaces and press Tab.';
  } else if ((m = detail.match(/^mismatched input (.+?) expecting (.+)$/))) {
    title = `Line ${line} has a surprise`;
    hint = `Sandscript found ${show(m[1])} but expected ${describe(m[2])}.`;
  } else if ((m = detail.match(/^extraneous input (.+?) expecting/))) {
    title = `Something extra on line ${line}`;
    hint = `Try removing ${show(m[1])}.`;
  } else if ((m = detail.match(/^no viable alternative at input (.+)$/))) {
    title = `Line ${line} is hard to read`;
    hint = `Sandscript got stuck near ${m[1]}. Check spelling, colons, and Tabs.`;
  } else if ((m = raw.match(/Unknown element type "(.+?)"/))) {
    hint = `There is no element called ${m[1]}. Check the spelling, or add "element ${m[1]}:".`;
  } else if ((m = raw.match(/Unknown field "(.+?)"/))) {
    hint = `This element has no "${m[1]}". Add "has ${m[1]} with 0" to the element first.`;
  } else if (/Instruction limit/.test(raw)) {
    hint = 'One tick took too many steps. Look for a loop that never ends, or a go_through with a huge range.';
  } else if (/AST validation failed/.test(raw)) {
    hint = raw.split('\n').slice(1, 2).join(' ');
  }

  return { title, hint, line, raw };
}
